/* From Uiverse.io by vishal2231179  - Tags:  */
.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  background-color: rgb(241, 241, 130);
  padding: 60px;
  padding-inline: 28px;
  border-radius: 20px;
  box-shadow: 4px 4px rgb(0, 2, 65);
  font-family: cursive;
}

.__UIV_SCOPE__ .heading {
  font-size: 25px;
  text-align: center;
  font-weight: 600;
  font-family: cursive;
}

.__UIV_SCOPE__ .form button {
  /* align-self: flex-end; */
  padding: 10px;
  border-radius: 10px;
  margin-top: 20px;
  background-color: rgb(241, 241, 130);
  box-shadow: 2px 3px rgb(0, 2, 65);

  color: rgb(0, 0, 0);
  font-size: medium;
  font-weight: 600;
  transition: 400ms;
  font-family: cursive;
}

.__UIV_SCOPE__ .form button:hover {
  background-color: rgb(235, 255, 59);
  transition: 400ms;
  cursor: pointer;
}

.__UIV_SCOPE__ .input {
  padding: 10px;
  width: 280px;
  border-radius: 10px;
  border-style: double;
  border-color: black;
  font-size: 15px;
  box-shadow: 2px 3px rgb(0, 2, 65);

  font-family: cursive;
}

.__UIV_SCOPE__ .forgot,
.__UIV_SCOPE__ a {
  padding-top: 10px;
  /* font-weight: 600; */
  color: rgba(0, 0, 0, 0.994);
  font-family: cursive;
  text-decoration: none;
  transition: 400ms;
}
.__UIV_SCOPE__ .forgot,
.__UIV_SCOPE__ a:hover {
  color: rgba(0, 0, 0, 0.703);
  transition: 400ms;
}

.__UIV_SCOPE__ .Mail,
.__UIV_SCOPE__ .Password {
  font-size: 16px;
  /* font-weight: 600; */
  font-family: cursive;
}
